'use client'
import React, { useEffect, useRef } from 'react'
import gsap from 'gsap'
import { DecisionPhaseProps, ResultType } from '@/lib/types'
import WantedStarsHUD from './WantedStarsHUD'

export default function DecisionPhase({ question = 1, onResult, sounds }: DecisionPhaseProps) {
    const qRef = useRef<HTMLDivElement | null>(null)
    const buttonsRef = useRef<(HTMLButtonElement | null)[]>([])

    useEffect(() => {
        try {
            if (sounds?.ambience) {
                sounds.ambience.fade(0.45, 0, 800)
                setTimeout(() => {
                    try {
                        sounds.ambience?.stop()
                    } catch (_) {}
                }, 850)
            }
        } catch (e) {
            console.warn('Audio notice in decision phase:', e)
        }

        if (qRef.current) {
            gsap.fromTo(
                qRef.current,
                { scale: 0.95, opacity: 0, y: 30 },
                { scale: 1, opacity: 1, y: 0, duration: 0.7, ease: 'power3.out' }
            )
        }

        buttonsRef.current.forEach((btn) => {
            if (btn) {
                gsap.to(btn, {
                    borderColor: 'rgba(255, 255, 255, 0.6)',
                    duration: 1.5,
                    repeat: -1,
                    yoyo: true,
                    ease: 'sine.inOut',
                })
            }
        })

        return () => {
            if (qRef.current) gsap.killTweensOf(qRef.current)
            buttonsRef.current.forEach((btn) => {
                if (btn) gsap.killTweensOf(btn)
            })
        }
    }, [sounds])

    const handleAnswer = (answer: 'yes' | 'no', e: React.MouseEvent<HTMLButtonElement>) => {
        const btn = e.currentTarget

        try {
            if (sounds?.warningAccept) {
                sounds.warningAccept.play()
            }
        } catch (_) {}

        gsap.to(btn, {
            backgroundColor: '#ffffff',
            color: '#000000',
            scale: 1.08,
            duration: 0.12,
            yoyo: true,
            repeat: 1,
            ease: 'power2.out',
            onComplete: () => {
                try {
                    if (typeof window !== 'undefined' && window.localStorage) {
                        if (question === 1) {
                            localStorage.setItem('programmerAnswer', answer)
                        } else {
                            localStorage.setItem('profileInterest', answer)
                        }
                    }
                } catch (err) {
                    console.warn('LocalStorage notice:', err)
                }

                if (question === 1) {
                    const res: ResultType = answer === 'yes' ? 'passed-access' : 'failed-denied'
                    onResult(res)
                } else {
                    const res: ResultType = answer === 'yes' ? 'passed-portfolio' : 'failed-redirect'
                    onResult(res)
                }
            },
        })
    }

    const isQ1 = question === 1

    return (
        <div
            style={{
                position: 'fixed',
                inset: 0,
                background: '#000',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                zIndex: 100,
                userSelect: 'none',
            }}
        >
            <div className="noise-overlay" />
            <div className="crt-scanlines" />

            {/* Top HUD with Wanted Stars */}
            <div
                style={{
                    position: 'absolute',
                    top: 32,
                    left: 40,
                    right: 40,
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    zIndex: 120,
                }}
            >
                <div
                    style={{
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        fontSize: '0.85rem',
                        letterSpacing: '0.25em',
                        color: '#f5a623',
                        textTransform: 'uppercase',
                    }}
                >
                    MISSION OBJECTIVE // CLEARANCE VERIFICATION
                </div>
                <WantedStarsHUD count={5} size={18} />
            </div>

            <div ref={qRef} className="decision-card">
                <div className="decision-question-sub">
                    MISSION SETUP // QUERY 0{question} OF 02
                </div>

                <h2 className={isQ1 ? 'decision-question-title q1-title' : 'decision-question-title q2-title'}>
                    {isQ1 ? (
                        <>
                            ARE YOU A<br />
                            PROGRAMMER?
                        </>
                    ) : (
                        <>
                            ARE YOU INTERESTED<br />
                            IN MY PROFILE?
                        </>
                    )}
                </h2>

                <div className="decision-buttons-container">
                    <button
                        ref={(el) => {
                            buttonsRef.current[0] = el
                        }}
                        className="decision-btn"
                        onClick={(e) => handleAnswer('yes', e)}
                        onMouseEnter={(e) => gsap.to(e.currentTarget, { scale: 1.06, duration: 0.2 })}
                        onMouseLeave={(e) => gsap.to(e.currentTarget, { scale: 1, duration: 0.2 })}
                    >
                        [ YES ]
                    </button>
                    <button
                        ref={(el) => {
                            buttonsRef.current[1] = el
                        }}
                        className="decision-btn"
                        onClick={(e) => handleAnswer('no', e)}
                        onMouseEnter={(e) => gsap.to(e.currentTarget, { scale: 1.06, duration: 0.2 })}
                        onMouseLeave={(e) => gsap.to(e.currentTarget, { scale: 1, duration: 0.2 })}
                    >
                        [ NO ]
                    </button>
                </div>
            </div>
        </div>
    )
}
